    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "hold_steps": 0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    if state["phase"] == "APPROACH":
        # Apply forward force to move into activation zone
        if x < ACTIVATION_X_MIN:
            fx = 30.0  # Increased forward force
        elif x > ACTIVATION_X_MAX:
            fx = 30.0  # Apply forward force to move out of activation zone
        else:
            # Apply backward force to trigger unlock
            fx = -35.0
        # Adjust force based on whisker readings to avoid obstacles
        if front < 2.5:  # If front whisker is close, apply lateral force
            fx += 10.0 * (2.5 - front)
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check unlock condition
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Check if commanded Fx is below threshold and speed is acceptable
        if cfg["act_lo"] <= x <= cfg["act_hi"] and fx < -34.0 and spd < 100.0:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Apply backward force to escape activation zone
        fx_cmd = -50.0  # Backward force to move out of activation zone
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust force based on whisker readings
        if front < 2.5:
            fx_cmd += 10.0 * (2.5 - front)
        if up < 2.5:
            fy_cmd += 10.0 * (2.5 - up)
        if down < 2.5:
            fy_cmd -= 10.0 * (2.5 - down)
        # Remove velocity adjustment
        state["t"] += 1
        if state["t"] > 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force to reach exit zone
        fx, fy = 50.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust force based on whisker readings
        if front < 2.5:
            fx += 10.0 * (2.5 - front)
        if up < 2.5:
            fy += 10.0 * (2.5 - up)
        if down < 2.5:
            fy -= 10.0 * (2.5 - down)
        if x >= _exit_x_min(sandbox):
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Track steps in exit zone
        state["hold_steps"] = state.get("hold_steps", 0) + 1
        if state["hold_steps"] >= 5:
            # Consider held, no further action needed
            pass
        fx, fy = 0.0, w_comp
