    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "hold_steps": 0,
            "activation_steps": 0,
            "in_activation_zone": False,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Determine if agent is in activation zone for whisker blind band
    in_activation_zone = (cfg["act_lo"] <= x <= cfg["act_hi"])

    if state["phase"] == "APPROACH":
        # Avoid walls using whiskers (whisker blind zone detection)
        if in_activation_zone:
            near_wall = False  # Ignore whisker readings in activation zone
        else:
            near_wall = front < 3.0  # Whisker blind zone detected

        if near_wall:
            # Apply backward force to move away from wall
            fx = -30.0
        else:
            # Apply forward force to move forward
            fx = 20.0
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            state["in_activation_zone"] = True
            state["activation_steps"] = state.get("activation_steps", 0) + 1
            if state["activation_steps"] >= 5:
                state["phase"] = "UNLOCK"
                state["t"] = 0
        else:
            state["in_activation_zone"] = False
            state["activation_steps"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply strictly backward force to trigger unlock
        vel = sandbox.get_agent_velocity()
        true_speed = math.sqrt(vel[0]**2 + vel[1]**2)
        if true_speed >= 100.0:
            # Speed is too high, stop applying force
            fx = 0.0
            fy = 0.0
        else:
            fx_cmd = -35.0  # Strictly below threshold
            fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
            fx = fx_cmd
            fy = fy_cmd

        # Check if out of activation zone
        if not in_activation_zone:
            state["phase"] = "ESCAPE"

        # Check structural impulse limit
        impulse = (fx + fy) * TIME_STEP
        if MEM.data["total_impulse"] + impulse > 125.0:
            fx, fy = 0.0, 0.0
        MEM.data["total_impulse"] += impulse

        state["t"] += 1
        if state["t"] > 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force to move out of activation zone
        fx = 35.0
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in exit zone
        if x >= _exit_x_min(sandbox):
            state["phase"] = "HOLD"
        else:
            # If still in activation zone, continue ESCAPE
            if in_activation_zone:
                state["phase"] = "ESCAPE"
            else:
                state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Check if in exit zone
        exit_x_min = _exit_x_min(sandbox)
        if x >= exit_x_min:
            state["hold_steps"] = state.get("hold_steps", 0) + 1
            if state["hold_steps"] >= 5:
                # Consider held, no further action needed
                pass
        else:
            state["hold_steps"] = 0
        fx, fy = 0.0, w_comp

    # Apply the computed force
    sandbox.apply_agent_force(fx, fy)
